import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskG solver = new TaskG();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskG {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int mod = 998244353;
            int n = in.nextInt();
            int k = in.nextInt();
            int[] v = new int[10];
            for (int i = 0; i < k; i++) {
                int x = in.nextInt();
                v[x] = 1;
            }
            int[] ans = {1};
            int p = n / 2;
            while (true) {
                if (p % 2 != 0) {
                    ans = multiplyMod(ans, v, mod);
                }
                p /= 2;
                if (p == 0) break;
                v = multiplyMod(v, v, mod);
            }
            int res = 0;
            for (int x : ans) {
                res = (int) ((res + (long) x * x) % mod);
            }
            out.println(res);
        }

        static int[] multiplyMod(int[] a, int[] b, int mod) {
            int need = a.length + b.length - 1;
            // Use BigInteger for exact polynomial multiplication
            BigInteger[] polyA = new BigInteger[a.length];
            BigInteger[] polyB = new BigInteger[b.length];
            for (int i = 0; i < a.length; i++) {
                polyA[i] = BigInteger.valueOf((a[i] % mod + mod) % mod);
            }
            for (int i = 0; i < b.length; i++) {
                polyB[i] = BigInteger.valueOf((b[i] % mod + mod) % mod);
            }
            BigInteger[] resBig = new BigInteger[need];
            for (int i = 0; i < need; i++) {
                resBig[i] = BigInteger.ZERO;
            }
            for (int i = 0; i < a.length; i++) {
                for (int j = 0; j < b.length; j++) {
                    resBig[i + j] = resBig[i + j].add(polyA[i].multiply(polyB[j]));
                }
            }
            int[] res = new int[need];
            BigInteger modBig = BigInteger.valueOf(mod);
            for (int i = 0; i < need; i++) {
                res[i] = resBig[i].mod(modBig).intValue();
            }
            return res;
        }
    }

    static class InputReader {
        final InputStream is;
        final byte[] buf = new byte[1024];
        int pos;
        int size;

        public InputReader(InputStream is) {
            this.is = is;
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c))
                c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sign;
        }

        int read() {
            if (size == -1)
                throw new InputMismatchException();
            if (pos >= size) {
                pos = 0;
                try {
                    size = is.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (size <= 0)
                    return -1;
            }
            return buf[pos++] & 255;
        }

        static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
